import React, { useState, useEffect } from 'react';
import { database, ref, onValue } from './firebase';
import { useNavigate } from 'react-router-dom';
import './ViewTransactions.css';

const ViewTransactions = () => {
  const [transactions, setTransactions] = useState([]);
  const [filteredTransactions, setFilteredTransactions] = useState([]);
  const [categories, setCategories] = useState([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('');
  const [selectedDate, setSelectedDate] = useState('');
  const [transactionsPerPage, setTransactionsPerPage] = useState(10); // Default to 10
  const [currentPage, setCurrentPage] = useState(1); // To handle pagination
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const navigate = useNavigate();

  useEffect(() => {
    const transactionsRef = ref(database, 'transactions');
    const unsubscribeTransactions = onValue(transactionsRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        const fetchedTransactions = Object.keys(data).map((key) => ({
          id: key,
          ...data[key],
        }));
        setTransactions(fetchedTransactions);

        // Extract unique categories
        const uniqueCategories = [
          ...new Set(fetchedTransactions.map((txn) => txn.category)),
        ];
        setCategories(uniqueCategories);

        // Set initial filtered transactions based on the default settings
        setFilteredTransactions(fetchedTransactions.slice(0, transactionsPerPage));
      } else {
        setTransactions([]);
        setFilteredTransactions([]);
        setCategories([]);
      }
    });

    return () => {
      unsubscribeTransactions();
    };
  }, [transactionsPerPage]);

  // Filter transactions based on search, selected filters, date range, etc.
  useEffect(() => {
    let filtered = transactions;

    // Filter by search query (description or category)
    if (searchQuery) {
      filtered = filtered.filter((txn) =>
        txn.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
        txn.category.toLowerCase().includes(searchQuery.toLowerCase())
      );
    }

    // Filter by category
    if (selectedCategory) {
      filtered = filtered.filter((txn) => txn.category === selectedCategory);
    }

    // Filter by specific date
    if (selectedDate) {
      filtered = filtered.filter((txn) => {
        return new Date(txn.date).toLocaleDateString() === new Date(selectedDate).toLocaleDateString();
      });
    }

    // Filter by date range
    if (startDate && endDate) {
      filtered = filtered.filter((txn) => {
        const txnDate = new Date(txn.date);
        return txnDate >= new Date(startDate) && txnDate <= new Date(endDate);
      });
    }

    // Pagination logic: Slice transactions to show based on the current page
    const startIndex = (currentPage - 1) * transactionsPerPage;
    const endIndex = startIndex + transactionsPerPage;
    filtered = filtered.slice(startIndex, endIndex);

    setFilteredTransactions(filtered);
  }, [searchQuery, selectedCategory, selectedDate, startDate, endDate, currentPage, transactions]);

  // Handle page changes for pagination
  const handlePagination = (page) => {
    setCurrentPage(page);
  };

  // Handle change in number of transactions per page
  const handleTransactionsPerPage = (e) => {
    setTransactionsPerPage(Number(e.target.value));
    setCurrentPage(1); // Reset to first page when number of transactions changes
  };

  const handleBackToDashboard = () => {
    navigate('/');
  };

  return (
    <div className="transaction-history-container">
      <h2 className="transaction-history-heading">Transaction History</h2>
      
      {/* Search and Filter UI */}
      <div className="filter-container">
        <input
          type="text"
          placeholder="Search by description or category"
          className="search-input"
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
        />
        
        <select
          value={selectedCategory}
          onChange={(e) => setSelectedCategory(e.target.value)}
          className="category-select"
        >
          <option value="">Select Category</option>
          {categories.map((category) => (
            <option key={category} value={category}>{category}</option>
          ))}
        </select>

        <input
          type="date"
          value={selectedDate}
          onChange={(e) => setSelectedDate(e.target.value)}
          className="date-input"
        />
        
        <div className="date-range">
          <input
            type="date"
            value={startDate}
            onChange={(e) => setStartDate(e.target.value)}
            placeholder="Start Date"
            className="date-input"
          />
          <input
            type="date"
            value={endDate}
            onChange={(e) => setEndDate(e.target.value)}
            placeholder="End Date"
            className="date-input"
          />
        </div>

        <select
          value={transactionsPerPage}
          onChange={handleTransactionsPerPage}
          className="transactions-per-page-select"
        >
          <option value="10">10 Transactions</option>
          <option value="20">20 Transactions</option>
          <option value="50">50 Transactions</option>
        </select>
      </div>

      {/* Display filtered transactions */}
      {filteredTransactions.length === 0 ? (
        <p>No transactions found.</p>
      ) : (
        <table className="transaction-table">
          <thead>
            <tr>
              <th>Amount</th>
              <th>Category</th>
              <th>Date</th>
              <th>Description</th>
              <th>Party Involved</th>
            </tr>
          </thead>
          <tbody>
            {filteredTransactions.map((txn) => (
              <tr
                key={txn.id}
                className={
                  txn.category === 'Udhar(Lent)'
                    ? 'lent-row'
                    : txn.category === 'Udhar(Borrowed)'
                    ? 'borrowed-row'
                    : ''
                }
              >
                <td>₹{txn.amount}</td>
                <td>{txn.category}</td>
                <td>{new Date(txn.date).toLocaleDateString()}</td>
                <td>{txn.description}</td>
                <td>{txn.udharParty || '-'}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      {/* Pagination Controls */}
      <div className="pagination">
        {Array.from({ length: Math.ceil(transactions.length / transactionsPerPage) }).map((_, index) => (
          <button
            key={index}
            className={`page-button ${currentPage === index + 1 ? 'active' : ''}`}
            onClick={() => handlePagination(index + 1)}
          >
            {index + 1}
          </button>
        ))}
      </div>

      {/* Back to Dashboard Button */}
      <div className="back-to-dashboard-btn-container">
        <button className="back-to-dashboard-btn" onClick={handleBackToDashboard}>
          Back to Dashboard
        </button>
      </div>
    </div>
  );
};

export default ViewTransactions;
