import React, { useState, useEffect } from "react";
import "./trans.css";

const categoryMappings = {
  Dining: ["restaurant", "cafe", "diner", "coffee", "food", "meal", "bar"],
  Shopping: ["amazon", "flipkart", "shop", "clothes", "shoes", "store"],
  Transport: ["uber", "ola", "taxi", "bus", "train", "flight", "car rental"],
  Entertainment: ["movie", "concert", "ticket", "show", "game", "event"],
  Groceries: ["supermarket", "groceries", "market", "grocery", "food", "veg", "fruit"],
  Bills: ["electricity", "internet", "water", "phone", "subscription"],
  Health: ["pharmacy", "medicine", "doctor", "hospital", "health", "clinic"],
};

const getSuggestedCategory = (description) => {
  const cleanedDescription = description.toLowerCase();

  for (const category in categoryMappings) {
    for (const keyword of categoryMappings[category]) {
      if (cleanedDescription.includes(keyword.toLowerCase())) {
        return category;
      }
    }
  }
  return ""; // Return empty string if no suggestion
};

const TransactionForm = ({
  addTransaction,
  categories,
  addCategory,
  deleteCategory,
}) => {
  const [amount, setAmount] = useState("");
  const [category, setCategory] = useState(""); // Manually entered category
  const [date, setDate] = useState("");
  const [note, setNote] = useState("");
  const [description, setDescription] = useState(""); // Add description state
  const [suggestedCategory, setSuggestedCategory] = useState(""); // Store suggested category
  const [isRecurring, setIsRecurring] = useState(false); // Track recurring transactions
  const [isUdhar, setIsUdhar] = useState(false); // Track Udhar (loan-related) transactions
  const [udharParty, setUdharParty] = useState(""); // Party involved in Udhar
  const [udharType, setUdharType] = useState(""); // Type of Udhar: Lent/Borrowed

  useEffect(() => {
    // Automatically set category to "Udhar" if Udhar is selected
    if (isUdhar) {
      setCategory("Udhar");
    } else {
      setCategory("");
    }

    // Update category based on Udhar Type (Lent/Borrowed)
    if (udharType) {
      setCategory(`Udhar(${udharType})`);
    }
  }, [isUdhar, udharType]); // This effect runs when `isUdhar` or `udharType` changes

  useEffect(() => {
    // Only suggest category if description is not empty and category is not manually entered
    if (description && !category) {
      const suggested = getSuggestedCategory(description);
      setSuggestedCategory(suggested);
    }
  }, [description, category]); // Trigger this effect on description or category change

  const handleSubmit = (e) => {
    e.preventDefault();

    // Check if amount, category, and date are filled before submitting
    if (!amount || (!category && !suggestedCategory) || !date) {
      alert("Please fill in all required fields: Amount, Category, and Date.");
      return;
    }

    // Validate Udhar details if Udhar is selected
    if (isUdhar && (!udharParty || !udharType)) {
      alert("Please provide all Udhar details: Party and Type (Lent/Borrowed).");
      return;
    }

    // Use suggested category if the user hasn't selected one manually
    const finalCategory = category || suggestedCategory;
    addTransaction({
      amount,
      category: finalCategory,
      date,
      note,
      description,
      isRecurring, // Include the recurring status
      isUdhar, // Include Udhar details
      udharParty: isUdhar ? udharParty : null,
      udharType: isUdhar ? udharType : null,
    });

    // Reset form fields
    setAmount("");
    setCategory("");
    setDate("");
    setNote("");
    setDescription("");
    setSuggestedCategory("");
    setIsRecurring(false); // Reset recurring checkbox
    setIsUdhar(false); // Reset Udhar checkbox
    setUdharParty("");
    setUdharType("");
  };

  return (
    <form onSubmit={handleSubmit} className="transaction-form">
      {/* Amount Input */}
      <div className="form-group">
        <label htmlFor="amount">Amount:</label>
        <input
          id="amount"
          type="number"
          value={amount}
          onChange={(e) => setAmount(e.target.value)}
          placeholder="Enter your amount"
          className="input-box"
          required
        />
      </div>

      {/* Description Input */}
      <div className="form-group">
        <label htmlFor="description">Transaction Description:</label>
        <input
          id="description"
          type="text"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          placeholder="Enter the transaction description (e.g., Amazon, Grocery)"
          className="input-box"
        />
      </div>

      {/* Category Input with Suggestions */}
      <div className="form-group">
        <label htmlFor="category">Category:</label>
        <input
          id="category"
          type="text"
          value={category || suggestedCategory} // Show suggested category if none selected
          onChange={(e) => setCategory(e.target.value)}
          placeholder="Select or type a category"
          className="input-box"
        />
        {suggestedCategory && !category && (
          <p className="suggested-category">Suggested Category: {suggestedCategory}</p>
        )}
      </div>

      {/* Date Input */}
      <div className="form-group">
        <label htmlFor="date">Date:</label>
        <input
          id="date"
          type="date"
          value={date}
          onChange={(e) => setDate(e.target.value)}
          className="input-box"
          required
        />
      </div>

      {/* Recurring Checkbox */}
      <div className="form-group">
        <label htmlFor="isRecurring" className="checkbox-label">
          <input
            id="isRecurring"
            type="checkbox"
            checked={isRecurring}
            onChange={(e) => setIsRecurring(e.target.checked)}
            className="checkbox-input"
          />
          Mark as Recurring
        </label>
      </div>

      {/* Udhar Section */}
      <div className="form-group">
        <label htmlFor="isUdhar" className="checkbox-label">
          <input
            id="isUdhar"
            type="checkbox"
            checked={isUdhar}
            onChange={(e) => setIsUdhar(e.target.checked)}
            className="checkbox-input"
          />
          Mark as Udhar (Loan)
        </label>
        {isUdhar && (
          <div className="udhar-details">
            <div className="form-group">
              <label htmlFor="udharParty">Party Involved:</label>
              <input
                id="udharParty"
                type="text"
                value={udharParty}
                onChange={(e) => setUdharParty(e.target.value)}
                placeholder="Enter the name of the person or entity"
                className="input-box"
                required={isUdhar}
              />
            </div>
            <div className="form-group">
              <label htmlFor="udharType">Udhar Type:</label>
              <select
                id="udharType"
                value={udharType}
                onChange={(e) => setUdharType(e.target.value)}
                className="input-box"
                required={isUdhar}
              >
                <option value="">Select Type</option>
                <option value="Lent">Lent</option>
                <option value="Borrowed">Borrowed</option>
              </select>
            </div>
          </div>
        )}
      </div>

      {/* Submit Button */}
      <button type="submit" className="submit-button">
        Add Transaction
      </button>
    </form>
  );
};

export default TransactionForm;
