import React, { useState, useEffect } from 'react';
import { Bar } from 'react-chartjs-2';
import { database, ref, onValue, push, set } from './firebase';
import './Part2_dashboard.css';

const Part2 = () => {
  const [income, setIncome] = useState([]);
  const [totalIncome, setTotalIncome] = useState(0);
  const [totalExpenses, setTotalExpenses] = useState(0);
  const [balance, setBalance] = useState(0);
  const [incomeSource, setIncomeSource] = useState('');
  const [incomeAmount, setIncomeAmount] = useState('');
  const [incomeDate, setIncomeDate] = useState('');
  const [savingsGoal, setSavingsGoal] = useState({ goal: 10000, saved: 5000 });

  // Fetch data and calculate totals
  useEffect(() => {
    const incomeRef = ref(database, 'income');
    const transactionsRef = ref(database, 'transactions');

    const unsubscribeIncome = onValue(incomeRef, (snapshot) => {
      const data = snapshot.val();
      const fetchedIncome = data ? Object.values(data) : [];
      setIncome(fetchedIncome);

      const total = fetchedIncome.reduce((sum, inc) => sum + parseFloat(inc.amount || 0), 0);
      setTotalIncome(total);
    });

    const unsubscribeExpenses = onValue(transactionsRef, (snapshot) => {
      const data = snapshot.val();
      const fetchedExpenses = data ? Object.values(data) : [];

      const total = fetchedExpenses.reduce((sum, txn) => sum + parseFloat(txn.amount || 0), 0);
      setTotalExpenses(total);
      setBalance(totalIncome - total);
    });

    return () => {
      unsubscribeIncome();
      unsubscribeExpenses();
    };
  }, [totalIncome]);

  // Add income to Firebase
  const addIncome = (e) => {
    e.preventDefault();
    if (!incomeSource || !incomeAmount || !incomeDate) {
      alert('Please fill in all fields');
      return;
    }

    const incomeRef = ref(database, 'income');
    const newIncomeRef = push(incomeRef);

    set(newIncomeRef, {
      source: incomeSource,
      amount: parseFloat(incomeAmount),
      date: incomeDate,
    })
      .then(() => {
        setIncomeSource('');
        setIncomeAmount('');
        setIncomeDate('');
      })
      .catch((error) => {
        console.error('Error adding income:', error);
      });
  };

  // Chart data
  const incomeVsExpenseData = {
    labels: ['Income', 'Expenses', 'Balance'],
    datasets: [
      {
        label: 'Amount (₹)',
        data: [totalIncome, totalExpenses, balance],
        backgroundColor: ['#36A2EB', '#FF6384', '#4BC0C0'],
      },
    ],
  };

  return (
    <div className="part2">
      {/* Form Section */}
      <div className="part2-form">
        <h3>Add Income</h3>
        <form onSubmit={addIncome}>
          <input
            type="text"
            placeholder="Source"
            value={incomeSource}
            onChange={(e) => setIncomeSource(e.target.value)}
          />
          <input
            type="number"
            placeholder="Amount"
            value={incomeAmount}
            onChange={(e) => setIncomeAmount(e.target.value)}
          />
          <input
            type="date"
            value={incomeDate}
            onChange={(e) => setIncomeDate(e.target.value)}
          />
          <button type="submit">Add Income</button>
        </form>

        {/* Savings Goal */}
        <h3>Savings Goal</h3>
        <div className="goal">
          <p>
            ₹{savingsGoal.saved} saved for a ₹{savingsGoal.goal} goal
          </p>
          <progress value={savingsGoal.saved} max={savingsGoal.goal}></progress>
        </div>
      </div>

      {/* Balance Summary Section */}
      <div className="part2-summary">
        <h3>Balance Summary</h3>
        <p><strong>Total Income:</strong> ₹{totalIncome}</p>
        <p><strong>Total Expenses:</strong> ₹{totalExpenses}</p>
        <p><strong>Balance:</strong> ₹{balance}</p>
      </div>

      {/* Chart Section */}
      <div className="part2-chart">
        <h3>Income vs. Expenses</h3>
        <Bar
          data={incomeVsExpenseData}
          options={{
            responsive: true,
            plugins: {
              legend: { position: 'top' },
              title: { display: true, text: 'Income vs. Expenses' },
            },
          }}
        />
      </div>
    </div>
  );
};

export default Part2;
