import React, { useState, useEffect } from "react";
import { database, ref, onValue, update } from "./firebase"; // Adjust the import path
import { useNavigate } from "react-router-dom";
import Calendar from "react-calendar";
import "react-calendar/dist/Calendar.css";
import "./RepaymentsPage.css";

const RepaymentsPage = () => {
  const [repayments, setRepayments] = useState([]);
  const [selectedRepayment, setSelectedRepayment] = useState(null);
  const [calendarDate, setCalendarDate] = useState(new Date());
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedCategory, setSelectedCategory] = useState("");
  const [loanAmount, setLoanAmount] = useState("");
  const [interestRate, setInterestRate] = useState("");
  const [repaymentPeriod, setRepaymentPeriod] = useState("");
  const [toastMessage, setToastMessage] = useState(""); // State to store toast message visibility
  const navigate = useNavigate();

  useEffect(() => {
    const transactionsRef = ref(database, "transactions");

    const unsubscribe = onValue(transactionsRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        const fetchedTransactions = Object.keys(data).map((key) => ({
          id: key,
          ...data[key],
        }));
        const filteredRepayments = fetchedTransactions.filter(
          (txn) => txn.isRecurring
        );
        setRepayments(filteredRepayments);
      } else {
        setRepayments([]);
      }
    });

    return () => unsubscribe();
  }, []);

  // Show toast message by updating state
  const showToast = (message) => {
    setToastMessage(message);
    setTimeout(() => {
      setToastMessage(""); // Clear toast message after 3 seconds
    }, 3000);
  };

  // Toggle Payment Status
  const toggleStatus = (id) => {
    const repaymentRef = ref(database, `transactions/${id}`);
    const updatedStatus = repayments.find((txn) => txn.id === id).status === "Paid" ? "Unpaid" : "Paid";
    
    update(repaymentRef, { status: updatedStatus }).then(() => {
      showToast(`Payment status updated to ${updatedStatus}`);
    });
  };

  const calculateProgress = (amount, paidAmount) => {
    const validPaidAmount = paidAmount ? parseFloat(paidAmount) : 0;
    const validAmount = amount ? parseFloat(amount) : 0;
  
    if (validAmount === 0) {
      return 0;
    }
  
    return (validPaidAmount / validAmount) * 100;
  };

  const filteredRepayments = repayments.filter((repayment) =>
    repayment.category.toLowerCase().includes(searchQuery.toLowerCase()) &&
    (selectedCategory ? repayment.category === selectedCategory : true)
  );

  const exportToCSV = () => {
    const csvData = repayments.map((repayment) => ({
      Category: repayment.category,
      Amount: repayment.amount,
      Date: repayment.date,
      Status: repayment.status,
    }));

    const csvContent =
      "data:text/csv;charset=utf-8," +
      ["Category", "Amount", "Date", "Status"].join(",") +
      "\n" +
      csvData
        .map((row) => `${row.Category},${row.Amount},${row.Date},${row.Status}`)
        .join("\n");

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", "repayments.csv");
    link.click();
  };

  const calculateRepayment = () => {
    const principal = parseFloat(loanAmount);
    const rate = parseFloat(interestRate) / 100 / 12;
    const time = parseInt(repaymentPeriod);

    const monthlyRepayment =
      (principal * rate) / (1 - Math.pow(1 + rate, -time));
    
    return monthlyRepayment.toFixed(2);
  };

  const handleCalendarClick = (date) => {
    setCalendarDate(date);
  };

  const repaymentsOnSelectedDate = filteredRepayments.filter(
    (repayment) => new Date(repayment.date).toDateString() === calendarDate.toDateString()
  );

  return (
    <div className="repayments-container">
      <h1>Upcoming Repayments</h1>
      <button className="back-to-dashboard-btn" onClick={() => navigate("/")}>
        Back to Dashboard
      </button>

      {/* Calendar Integration */}
      <div className="calendar-section">
        <h2>Select a Date to View Repayments</h2>
        <Calendar
          value={calendarDate}
          onClickDay={handleCalendarClick}
          className="repayment-calendar"
        />
      </div>

      {/* Search and Filter */}
      <div className="search-section">
        <input
          type="text"
          placeholder="Search repayments..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
        />
        <select
          onChange={(e) => setSelectedCategory(e.target.value)}
          value={selectedCategory}
        >
          <option value="">All Categories</option>
          <option value="Loan">Loan</option>
          <option value="Credit Card">Credit Card</option>
        </select>
      </div>

      {/* Repayments for the selected date */}
      <div className="selected-date-repayments">
        <h3>Repayments on {calendarDate.toDateString()}</h3>
        {repaymentsOnSelectedDate.length > 0 ? (
          repaymentsOnSelectedDate.map((repayment) => (
            <div key={repayment.id} className="repayment-card">
              <div className="repayment-info">
                <strong>{repayment.category}</strong>: ₹{repayment.amount}
              </div>
              <div className="repayment-due">
                <span>Due on: </span>
                <strong>{new Date(repayment.date).toLocaleDateString()}</strong>
              </div>
              <div className="repayment-status">
                <strong>Status:</strong>
                <span>{repayment.status}</span>
                <button onClick={() => toggleStatus(repayment.id)}>
                  Mark as {repayment.status === "Paid" ? "Unpaid" : "Paid"}
                </button>
              </div>
            </div>
          ))
        ) : (
          <p>No repayments found for the selected date.</p>
        )}
      </div>

      {/* Full Repayments List */}
      <h2>All Upcoming Repayments</h2>
      {filteredRepayments.length > 0 ? (
        <div className="repayments-list">
          {filteredRepayments.map((repayment) => (
            <div key={repayment.id} className="repayment-card">
              <div className="repayment-info">
                <strong>{repayment.category}</strong>: ₹{repayment.amount}
              </div>
              <div className="repayment-due">
                <span>Due in </span>
                <strong>
                  {Math.ceil(
                    (new Date(repayment.date) - new Date()) / (1000 * 60 * 60 * 24)
                  )}{" "}
                  days
                </strong>
              </div>
              <div className="repayment-status">
                <strong>Status:</strong>
                <span>{repayment.status}</span>
                <button onClick={() => toggleStatus(repayment.id)}>
                  Mark as {repayment.status === "Paid" ? "Unpaid" : "Paid"}
                </button>
              </div>
            </div>
          ))}
        </div>
      ) : (
        <p>No upcoming repayments found.</p>
      )}

      {/* Export Button */}
      <button onClick={exportToCSV}>Export to CSV</button>


    {/* Repayment Calculator */}
<div className="repayment-calculator">
  <h3 className="calculator-title">Repayment Calculator</h3>
  <div className="calculator-inputs">
    <label htmlFor="loanAmount">Loan Amount:</label>
    <input
      id="loanAmount"
      type="number"
      value={loanAmount}
      onChange={(e) => setLoanAmount(e.target.value)}
      placeholder="Enter loan amount"
    />

    <label htmlFor="interestRate">Interest Rate (Annual):</label>
    <input
      id="interestRate"
      type="number"
      value={interestRate}
      onChange={(e) => setInterestRate(e.target.value)}
      placeholder="Enter interest rate"
    />

    <label htmlFor="repaymentPeriod">Repayment Period (Months):</label>
    <input
      id="repaymentPeriod"
      type="number"
      value={repaymentPeriod}
      onChange={(e) => setRepaymentPeriod(e.target.value)}
      placeholder="Enter period in months"
    />

    <button
      className="calculate-button"
      onClick={() => alert(`Monthly Repayment: ₹${calculateRepayment()}`)}
    >
      Calculate Repayment
    </button>
  </div>
  <div className="calculated-repayment">
    {loanAmount && interestRate && repaymentPeriod && (
      <p className="result">
        <strong>Estimated Monthly Repayment: </strong> ₹{calculateRepayment()}
      </p>
    )}
  </div>
</div>


      {/* Toast Notification */}
      {toastMessage && (
        <div className="toast-container">
          <div className="toast">
            <span>{toastMessage}</span>
          </div>
        </div>
      )}
    </div>
  );
};

export default RepaymentsPage;
